+ 	struct acpi_sbs *sbs;
++	struct list_head list;		/* node in sbs_hook_battery_list */
+ 	unsigned long update_time;
+ 	char name[8];
+ 	char manufacturer_name[ACPI_SBS_BLOCK_MAX];
+@@ -518,6 +520,145 @@ static int acpi_battery_read(struct acpi_battery *battery)
